import Foundation

public struct Opening: Codable, Sendable, Equatable {
    public let eco: String
    public let name: String
}

/// Opening names keyed by FEN fields 1-4 (placement, side, castling, en passant).
/// Data: lichess-org/chess-openings (CC0), generated by scripts/gen-openings.sh.
public enum OpeningBook {
    private struct Row: Decodable {
        let key: String
        let eco: String
        let name: String
    }

    private static let table: [String: Opening] = {
        guard let url = Bundle.module.url(forResource: "openings", withExtension: "json"),
              let data = try? Data(contentsOf: url),
              let rows = try? JSONDecoder().decode([Row].self, from: data) else { return [:] }
        return Dictionary(rows.map { ($0.key, Opening(eco: $0.eco, name: $0.name)) },
                          uniquingKeysWith: { first, _ in first })
    }()

    private static func key(_ fen: String) -> String {
        fen.split(separator: " ").prefix(4).joined(separator: " ")
    }

    public static func lookup(fen: String) -> Opening? {
        table[key(fen)]
    }

    /// The last book opening seen while replaying `moves` (UCI) from `startFen`.
    /// Stops at the first illegal move. Nil when no position along the way is in the book.
    public static func deepest(startFen: String, moves: [String]) -> Opening? {
        var fen = startFen
        var found = lookup(fen: fen)
        for move in moves {
            guard let applied = Rules.apply(uci: move, to: fen) else { break }
            fen = applied.fenAfter
            if let opening = lookup(fen: fen) { found = opening }
        }
        return found
    }
}
